# Writes the hedra command files of the marble labyrinth's world and game pieces: table.txt (the
# plank table top), dish.txt, plant.txt, books.txt, cup.txt (props on the table), marble.txt,
# wall.txt (a maze wall), hole.txt, goal.txt (the goal hole with its flag), start.txt (the start
# ring), spark.txt. Run from models/env: /usr/bin/python3 make_env.py
# Up Z, front -Y (hedra); colours exact WoodSpark. World (glTF) = (x, z, -y) of hedra.
import math

HEX = {"cream": "f5eeb0", "honey": "fabf61", "orange": "e08d51", "mauve": "8a5865", "plum": "452b3f",
       "pine": "2c5e3b", "green": "609c4f", "olive": "c6cc54", "sky": "78c2d6", "blue": "5479b0",
       "slate": "56546e", "grey": "839fa6", "pale": "e0d3c8", "red": "f05b5b", "wine": "8f325f",
       "pink": "eb6c98"}
def col(n):
    h = HEX[n]; r, g, b = (int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
    return f"--base-color {r:.4f} {g:.4f} {b:.4f}"

files = {}

# ---------------------------------------------------------------- table top
# planks run left-right (along x), 1.5 m wide, with dark seams 0.16 m wide between them
seams = []
y = -9.0
while y < 9.0:
    seams.append(f"(pos.y > {y - 0.08:.2f} && pos.y < {y + 0.08:.2f})")
    y += 1.5
# a few darker knots / boards
files["table"] = f"""# Table top: a plank surface 24 x 18 m at z 0 (the box stands on it), planks along x with dark
# seams; only the top face (the camera never sees the rest). Generated by make_env.py.
new
material new Board {col('mauve')} --no-slot
material new Seam {col('plum')} --no-slot
add mesh grid --name Table --size 1 --x-subdivisions 2 --y-subdivisions 112 --location 0 0 0
scale 24 18 1
apply --scale
material assign Board
mode edit
select face where "{' || '.join(seams)}"
material assign Seam
mode object
shade flat
export table.glb
"""

# ---------------------------------------------------------------- dish (holds the spare marbles)
files["dish"] = f"""# Dish: a shallow eight-sided ceramic bowl 1.9 m across, 0.4 m tall, for the spare marbles.
# Origin on the ground under its centre. Generated by make_env.py.
new
material new Glaze {col('red')} --no-slot
material new Inside {col('pink')} --no-slot
add mesh cone --name Dish --vertices 8 --radius1 0.62 --radius2 0.95 --depth 0.4 --location 0 0 0.2
material assign Glaze
mode edit
select face where "normal.z > 0.9"
inset 0.12
extrude 0 0 -0.26
material assign Inside
select face where "normal.z < -0.9 && pos.z < -0.15"
delete only-faces
mode object
shade flat
export dish.glb
"""

# ---------------------------------------------------------------- potted plant
leaves = []
for i in range(7):
    a = 360.0 * i / 7 + 20
    tilt = 38 if i % 2 else 22
    L = 1.35 if i % 2 else 1.6
    leaves.append(f"add mesh cube --name L{i} --size 1 --location 0 0 0")
    leaves.append(f"scale 0.42 0.12 {L}\napply --scale\ntranslate 0 0 {L / 2:.3f}\napply --location")
    leaves.append("mode edit\nselect vert where \"pos.z > " + f"{L - 0.25:.2f}" + "\"\nscale 0.2 1 1\nmode object")
    leaves.append(f"set rotation {tilt} 0 {a:.1f}\napply --rotation\ntranslate 0 0 0.95\napply --location")
files["plant"] = f"""# Potted plant: a terracotta pot (eight-sided, tapering) with a rim and seven pointed strap leaves
# fanning out. 2.4 m across, 2.7 m tall. Origin on the ground under the pot. Generated by make_env.py.
new
material new Pot {col('orange')} --no-slot
material new Soil {col('plum')} --no-slot
material new Leaf {col('green')} --no-slot
add mesh cone --name Pot --vertices 8 --radius1 0.5 --radius2 0.66 --depth 0.9 --location 0 0 0.45
add mesh cylinder --name Rim --vertices 8 --radius 0.76 --depth 0.22 --location 0 0 0.95
select Pot Rim
active Pot
join
material assign Pot
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
add mesh cylinder --name Soil --vertices 8 --radius 0.62 --depth 0.05 --location 0 0 1.03
material assign Soil
""" + "\n".join(leaves) + f"""
select {' '.join(f'L{i}' for i in range(7))}
active L0
join
rename L0 Leaves
material assign Leaf
select all
shade flat
export plant.glb
"""

# ---------------------------------------------------------------- book stack
books = [("wine", 2.6, 1.9, 0.38, 0.0, 0), ("blue", 2.3, 1.7, 0.34, 0.38, 9), ("green", 2.0, 1.5, 0.3, 0.72, -6)]
bk = []
for i, (c, w, d, h, z, yaw) in enumerate(books):
    bk.append(f"add mesh cube --name Cover{i} --size 1 --location 0 0 {z + h / 2:.3f}")
    bk.append(f"scale {w} {d} {h}\napply --scale")
    bk.append(f"add mesh cube --name Pages{i} --size 1 --location 0.06 0.06 {z + h / 2:.3f}")
    bk.append(f"scale {w - 0.06:.2f} {d - 0.08:.2f} {h * 0.7:.3f}\napply --scale")
    bk.append(f"material assign Pages")
    bk.append(f"select Cover{i}\nactive Cover{i}\nmaterial assign C{i}")
    bk.append(f"select Cover{i} Pages{i}\nactive Cover{i}\njoin\nset rotation 0 0 {yaw}\napply --rotation")
files["books"] = f"""# Book stack: three closed books (wine, blue, green covers, cream pages showing on the long side),
# each turned a little. Origin on the ground. Generated by make_env.py.
new
material new Pages {col('cream')} --no-slot
material new C0 {col('wine')} --no-slot
material new C1 {col('blue')} --no-slot
material new C2 {col('green')} --no-slot
""" + "\n".join(bk) + f"""
select Cover0 Cover1 Cover2
active Cover0
join
rename Cover0 Books
mode edit
select face where "normal.z < -0.9 && pos.z < 0.05"
delete only-faces
mode object
shade flat
export books.glb
"""

# ---------------------------------------------------------------- cup (pencil cup)
pencils = []
for i, (x, y, c, h) in enumerate([(0.15, 0.1, 'olive', 2.2), (-0.18, 0.05, 'red', 2.0), (0.0, -0.2, 'sky', 2.35)]):
    pencils.append(f"add mesh cylinder --name P{i} --vertices 6 --radius 0.1 --depth {h} --location {x} {y} {h / 2:.2f}")
    pencils.append(f"set rotation {8 * (i - 1)} {10 - 8 * i} 0\napply --rotation")
    pencils.append(f"material assign Pen{i}")
files["cup"] = f"""# Pencil cup: an eight-sided slate cup with three pencils leaning out. Origin on the ground.
new
material new Cup {col('slate')} --no-slot
material new Pen0 {col('olive')} --no-slot
material new Pen1 {col('red')} --no-slot
material new Pen2 {col('sky')} --no-slot
add mesh cylinder --name Cup --vertices 8 --radius 0.5 --depth 1.2 --location 0 0 0.6
material assign Cup
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
""" + "\n".join(pencils) + f"""
select all
shade flat
export cup.glb
"""

# ---------------------------------------------------------------- marble
files["marble"] = f"""# Marble: a faceted glass ball r 0.26 m with a pale swirl band round it (so its roll reads).
# Origin at its centre. Generated by make_env.py.
new
material new Glass {col('blue')} --no-slot
material new Swirl {col('pale')} --no-slot
add mesh ico-sphere --name Marble --subdivisions 2 --radius 0.26 --location 0 0 0
material assign Glass
mode edit
select face where "pos.x > -0.07 && pos.x < 0.07"
material assign Swirl
mode object
shade flat
export marble.glb
"""

# ---------------------------------------------------------------- maze wall
files["wall"] = f"""# Maze wall: a dark wooden rail 2.0 m long (along x), 0.26 m thick, 0.45 m tall, its top orange.
# Origin at the centre of its foot (the game puts it on the tilting floor). Generated by make_env.py.
new
material new Rail {col('mauve')} --no-slot
material new Top {col('orange')} --no-slot
add mesh cube --name Wall --size 1 --location 0 0 0.225
scale 2.0 0.26 0.45
apply --scale
material assign Rail
mode edit
select face where "normal.z > 0.9"
material assign Top
select face where "normal.z < -0.9"
delete only-faces
mode object
shade flat
export wall.glb
"""

# ---------------------------------------------------------------- hole
files["hole"] = f"""# Hole: a dark pit disc r 0.38 m just above the floor, ringed by a steel rim (torus) proud of it.
# Origin at the centre on the floor. Generated by make_env.py.
new
material new Pit {col('plum')} --no-slot
material new Rim {col('grey')} --no-slot
add mesh cylinder --name Pit --vertices 12 --radius 0.38 --depth 0.02 --location 0 0 0.03
material assign Pit
mode edit
select face where "normal.z < 0.9"
delete only-faces
mode object
add mesh torus --name Rim --major-segments 14 --minor-segments 4 --major-radius 0.43 --minor-radius 0.075 --location 0 0 0.05
material assign Rim
shade flat
export hole.glb
"""

# ---------------------------------------------------------------- goal (a hole with a green rim and a flag)
files["goal"] = f"""# Goal: a hole with a green rim, and a flag (a slate pole, a red pennant) standing behind it.
# Origin at the hole's centre on the floor. Generated by make_env.py.
new
material new Pit {col('plum')} --no-slot
material new Rim {col('olive')} --no-slot
material new Pole {col('slate')} --no-slot
material new Flag {col('red')} --no-slot
add mesh cylinder --name Pit --vertices 12 --radius 0.38 --depth 0.02 --location 0 0 0.03
material assign Pit
mode edit
select face where "normal.z < 0.9"
delete only-faces
mode object
add mesh torus --name Rim --major-segments 14 --minor-segments 4 --major-radius 0.45 --minor-radius 0.09 --location 0 0 0.06
material assign Rim
add mesh cylinder --name Pole --vertices 6 --radius 0.06 --depth 1.6 --location 0.0 0.6 0.8
material assign Pole
add mesh cube --name Flag --size 1 --location 0.36 0.6 1.32
scale 0.66 0.08 0.48
apply --scale
mode edit
select vert where "pos.x > 0.2"
scale 1 1 0.25
mode object
material assign Flag
shade flat
export goal.glb
"""

# ---------------------------------------------------------------- start ring
files["start"] = f"""# Start ring: a sky-blue ring proud of the floor where each marble drops in. Origin at its centre.
new
material new Ring {col('sky')} --no-slot
add mesh torus --name Start --major-segments 14 --minor-segments 4 --major-radius 0.4 --minor-radius 0.07 --location 0 0 0.05
material assign Ring
shade flat
export start.glb
"""

# ---------------------------------------------------------------- spark
files["spark"] = f"""# Spark: a small octahedron for confetti bursts. Origin at its centre.
new
material new Spark {col('cream')} --no-slot
add mesh ico-sphere --name Spark --subdivisions 1 --radius 0.11 --location 0 0 0
material assign Spark
shade flat
export spark.glb
"""

for name, txt in files.items():
    with open(f"{name}.txt", "w") as f:
        f.write(txt)
print("wrote", ", ".join(f"{n}.txt" for n in files))
